8	namespace seed_a_backend.Api.Application;
9	
10	/// <summary>
11	/// Preisberechnung ausschließlich serverseitig aus PriceCategory (AD-3, NFR-6) — die Command-Form
12	/// enthält bewusst kein Preisfeld, ein evtl. clientseitig berechneter Preis kann also strukturell
13	/// nicht mitgesendet werden. Konflikterkennung über den Constraint-Namen aus der SqlException
14	/// (AD-1): nur eine Verletzung des Sitzplatz-Unique-Index führt zu SEAT_CONFLICT, eine Reference-
15	/// Kollision löst eine interne Neuerzeugung mit Retry aus, die der Besucher nie sieht.
16	/// </summary>
17	public class BookingService(AppDbContext db)
18	{
19	    private const string ReferenceAlphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"; // ohne 0/O/1/I/L (AD-4)
20	    private const int ReferenceLength = 8;
21	    private const int MaxReferenceAttempts = 5;
22	    private const int MaxNameLength = 200;
23	    private const int MaxEmailLength = 254; // RFC 5321
24	
25	    public async Task<BookingCreateResult> CreateBookingAsync(CreateBookingCommand command, CancellationToken ct = default)
26	    {
27	        var room = await (
28	            from e in db.Events
29	            join r in db.Rooms on e.RoomId equals r.Id
30	            where e.Id == command.EventId
31	            select r
32	        ).SingleOrDefaultAsync(ct);
33	
34	        if (room is null)
35	        {
36	            return new BookingCreateResult.EventNotFound();
37	        }
38	
39	        if (string.IsNullOrWhiteSpace(command.Name))
40	        {
41	            return new BookingCreateResult.ValidationFailed("Der Name darf nicht leer sein.");
42	        }
43	
44	        if (command.Name.Length > MaxNameLength)
45	        {
46	            return new BookingCreateResult.ValidationFailed($"Der Name darf höchstens {MaxNameLength} Zeichen lang sein.");
47	        }
48	
49	        if (command.Email.Length > MaxEmailLength)
50	        {
51	            return new BookingCreateResult.ValidationFailed($"Die E-Mail-Adresse darf höchstens {MaxEmailLength} Zeichen lang sein.");
52	        }
53	
54	        if (!MailAddress.TryCreate(command.Email, out var parsedEmail))
55	        {
56	            return new BookingCreateResult.ValidationFailed("Die E-Mail-Adresse ist ungültig.");
57	        }
58	
59	        if (command.Positions.Count == 0)
60	        {
61	            return new BookingCreateResult.ValidationFailed("Es muss mindestens ein Sitzplatz ausgewählt sein.");
62	        }
63	
64	        var maxSeatsInRoom = room.RowLabels.Count * room.ColumnCount;
65	        if (command.Positions.Count > maxSeatsInRoom)
66	        {
67	            return new BookingCreateResult.ValidationFailed("Es können nicht mehr Sitzplätze gebucht werden, als der Raum enthält.");
68	        }
69	
70	        if (command.Positions.GroupBy(p => (p.RowLabel, p.ColumnNumber)).Any(g => g.Count() > 1))
71	        {
72	            return new BookingCreateResult.ValidationFailed("Ein Sitzplatz ist mehrfach in der Auswahl enthalten.");
73	        }
74	
75	        var priceCategories = await db.PriceCategories
76	            .Where(pc => pc.EventId == command.EventId)
77	            .ToDictionaryAsync(pc => pc.Id, ct);
78	
79	        foreach (var position in command.Positions)
80	        {
81	            var seatCode = SeatCode(position.RowLabel, position.ColumnNumber);
82	
83	            if (!room.RowLabels.Contains(position.RowLabel))
84	            {
85	                return new BookingCreateResult.ValidationFailed($"Sitzplatz '{seatCode}' existiert nicht in diesem Raum.");
86	            }
87	            if (position.ColumnNumber < 1 || position.ColumnNumber > room.ColumnCount)
88	            {
89	                return new BookingCreateResult.ValidationFailed($"Sitzplatz '{seatCode}' liegt außerhalb des Sitzplans.");
90	            }
91	            if (room.AisleColumns.Contains(position.ColumnNumber))
92	            {
93	                return new BookingCreateResult.ValidationFailed($"'{seatCode}' ist ein Gang, kein Sitzplatz.");
94	            }
95	            if (!priceCategories.ContainsKey(position.PriceCategoryId))
96	            {
97	                return new BookingCreateResult.ValidationFailed("Die gewählte Preiskategorie gehört nicht zu dieser Veranstaltung.");
98	            }
99	        }
100	
101	        // Deterministische Reihenfolge (RowLabel, dann ColumnNumber) zur Deadlock-Vermeidung bei
102	        // gegenläufigen gleichzeitigen Insert-Reihenfolgen (AD-1).
103	        var orderedPositions = command.Positions
104	            .OrderBy(p => p.RowLabel, StringComparer.Ordinal)
105	            .ThenBy(p => p.ColumnNumber)
106	            .ToList();
107	
108	        var booking = new Booking
109	        {
110	            Reference = GenerateReference(),
111	            Name = command.Name.Trim(),
112	            Email = parsedEmail!.Address,
113	        };
114	        foreach (var position in orderedPositions)
115	        {
116	            booking.Positions.Add(new BookingPosition
117	            {
118	                EventId = command.EventId,
119	                RowLabel = position.RowLabel,
120	                ColumnNumber = position.ColumnNumber,
121	                PriceCategoryId = position.PriceCategoryId,
122	            });
123	        }
124	
125	        db.Bookings.Add(booking);
126	
127	        for (var attempt = 0; attempt < MaxReferenceAttempts; attempt++)
128	        {
129	            try
130	            {
131	                await db.SaveChangesAsync(ct);
132	
133	                var positionResults = orderedPositions
134	                    .Select(p => new BookingPositionResult(p.RowLabel, p.ColumnNumber, ToSummary(priceCategories[p.PriceCategoryId])))
135	                    .ToList();
136	                var totalPrice = orderedPositions.Sum(p => priceCategories[p.PriceCategoryId].Preis);
137	
138	                return new BookingCreateResult.Success(new BookingResult(
139	                    booking.Reference, booking.Name,
140	                    booking.CancelledAtUtc is null ? "aktiv" : "storniert",
141	                    positionResults, totalPrice));
142	            }
143	            catch (DbUpdateException ex) when (ex.InnerException is SqlException { Number: 2601 or 2627 } sql)
144	            {
145	                if (sql.Message.Contains(AppDbContext.BookingPositionSeatUniqueConstraintName))
146	                {
147	                    // Re-Read dient nur der Nutzer-Kommunikation, nicht der Korrektheitsprüfung
148	                    // (die ist bereits durch den fehlgeschlagenen Insert entschieden, AD-1).
149	                    var occupied = await db.BookingPositions
150	                        .Where(bp => bp.EventId == command.EventId && bp.CancelledAtUtc == null)
151	                        .Select(bp => new { bp.RowLabel, bp.ColumnNumber })
152	                        .ToListAsync(ct);
153	                    var occupiedSet = occupied.Select(o => (o.RowLabel, o.ColumnNumber)).ToHashSet();
154	                    var conflicting = orderedPositions
155	                        .Where(p => occupiedSet.Contains((p.RowLabel, p.ColumnNumber)))
156	                        .Select(p => SeatCode(p.RowLabel, p.ColumnNumber))
157	                        .ToList();
158	                    if (conflicting.Count == 0)
159	                    {
160	                        // Die konkurrierende Buchung wurde zwischen dem fehlgeschlagenen Insert und
161	                        // diesem Re-Read bereits storniert — der Konflikt ist real (Insert ist gescheitert),
162	                        // aber keine der angefragten Positionen ist mehr belegt. Sicherer Fallback: alle
163	                        // angefragten Sitzplätze melden, statt eine leere Liste zurückzugeben.
164	                        conflicting = orderedPositions
165	                            .Select(p => SeatCode(p.RowLabel, p.ColumnNumber))
166	                            .ToList();
167	                    }
168	                    return new BookingCreateResult.SeatConflict(conflicting);
169	                }
170	
171	                if (sql.Message.Contains(AppDbContext.BookingReferenceUniqueConstraintName))
172	                {
173	                    booking.Reference = GenerateReference();
174	                    continue;
175	                }
176	
177	                throw;
178	            }
179	        }
180	
181	        throw new InvalidOperationException("Es konnte keine eindeutige Buchungsreferenz erzeugt werden.");
182	    }
183	
184	    /// <summary>Liest eine Buchung per Referenz (case-insensitiver Vergleich über die Spaltenkollation, AD-4).</summary>
185	    public async Task<BookingResult?> GetBookingByReferenceAsync(string reference, CancellationToken ct = default)
186	    {
187	        var booking = await db.Bookings
188	            .Include(b => b.Positions)
189	            .SingleOrDefaultAsync(b => b.Reference == reference, ct);
190	
191	        if (booking is null)
192	        {
193	            return null;
194	        }
195	
196	        var priceCategoryIds = booking.Positions.Select(p => p.PriceCategoryId!.Value).ToHashSet();
197	        var priceCategories = await db.PriceCategories
198	            .Where(pc => priceCategoryIds.Contains(pc.Id))
199	            .ToDictionaryAsync(pc => pc.Id, ct);
200	
201	        var orderedPositions = booking.Positions
202	            .OrderBy(p => p.RowLabel, StringComparer.Ordinal)
203	            .ThenBy(p => p.ColumnNumber)
204	            .ToList();
205	
206	        var positionResults = orderedPositions
207	            .Select(p => new BookingPositionResult(p.RowLabel, p.ColumnNumber, ToSummary(priceCategories[p.PriceCategoryId!.Value])))
208	            .ToList();
209	        var totalPrice = orderedPositions.Sum(p => priceCategories[p.PriceCategoryId!.Value].Preis);
210	
211	        return new BookingResult(
212	            booking.Reference, booking.Name,
213	            booking.CancelledAtUtc is null ? "aktiv" : "storniert",
214	            positionResults, totalPrice);
215	    }
216	
217	    private static PriceCategorySummary ToSummary(PriceCategory pc) => new(pc.Id, pc.Name, pc.Preis);
218	
