13	    {
14	        if (request.Positionen is null || request.Positionen.Any(p => p is null))
15	        {
16	            return BadRequest(new ErrorEnvelopeDto(
17	                "VALIDATION_ERROR", "Die Anfrage enthält ungültige oder unvollständige Daten."));
18	        }
19	
20	        var command = new CreateBookingCommand(
21	            request.EventId, request.Name, request.Email,
