23	                .Select(p => new CreateBookingPositionCommand(p.RowLabel, p.ColumnNumber, p.PriceCategoryId))
24	                .ToList());
25	
26	        var result = await bookingService.CreateBookingAsync(command, ct);
27	
28	        return result switch
29	        {
30	            BookingCreateResult.Success s => Created($"/api/bookings/{s.Booking.Reference}", ToDto(s.Booking)),
31	            BookingCreateResult.EventNotFound => NotFound(new ErrorEnvelopeDto("EVENT_NOT_FOUND", "Veranstaltung nicht gefunden.")),
32	            BookingCreateResult.ValidationFailed v => BadRequest(new ErrorEnvelopeDto("VALIDATION_ERROR", v.Message)),
33	            BookingCreateResult.SeatConflict c => Conflict(new ErrorEnvelopeDto(
34	                "SEAT_CONFLICT", "Mindestens ein gewählter Sitzplatz ist inzwischen belegt.", c.ConflictingSeats)),
35	            _ => throw new InvalidOperationException("Unbekanntes BookingCreateResult."),
36	        };
37	    }
38	
39	    [HttpGet("{reference}")]
