43	
44	        return result is null
45	            ? NotFound(new ErrorEnvelopeDto("BOOKING_NOT_FOUND", "Buchung nicht gefunden."))
46	            : Ok(ToDto(result));
47	    }
48	
49	    private static BookingDto ToDto(BookingResult result) => new(
50	        result.Reference, result.Name, result.Status,
51	        result.Positionen
52	            .Select(p => new BookingPositionDto(
53	                p.RowLabel, p.ColumnNumber,
