import { CurrencyPipe } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { Router, RouterLink } from '@angular/router';

import { Booking } from '../../core/api/booking';

@Component({
  selector: 'app-booking-detail',
  imports: [CurrencyPipe, RouterLink],
  templateUrl: './booking-detail.html',
  styleUrl: './booking-detail.scss'
})
export class BookingDetailPage {
  private readonly router = inject(Router);

  readonly booking = signal<Booking | null>(null);
  readonly notAvailable = signal(false);
  readonly copied = signal(false);

  constructor() {
    const state = this.router.getCurrentNavigation()?.extras.state as { booking?: Booking } | undefined;
    if (state?.booking) {
      this.booking.set(state.booking);
    } else {
      this.notAvailable.set(true);
    }
  }

  formattedReference(): string {
    const reference = this.booking()?.reference ?? '';
    return `${reference.slice(0, 4)}-${reference.slice(4, 8)}`;
  }

  async copyReference(): Promise<void> {
    const reference = this.booking()?.reference;
    if (!reference) {
      return;
    }
    try {
      await navigator.clipboard.writeText(reference);
      this.copied.set(true);
    } catch {
      this.copied.set(false);
    }
  }
}

@if (booking(); as b) {
  <article class="booking-detail">
    <p class="booking-detail__confirmation" aria-live="polite">Buchung bestätigt. Referenz: {{ formattedReference() }}</p>

    <span class="badge" [class.badge--active]="b.status === 'aktiv'" [class.badge--cancelled]="b.status === 'storniert'">
      {{ b.status === 'aktiv' ? 'Aktiv' : 'Storniert' }}
    </span>

    <div class="booking-detail__reference">
      <span class="booking-detail__reference-value">{{ formattedReference() }}</span>
      <button type="button" class="booking-detail__copy" (click)="copyReference()">
        {{ copied() ? 'Kopiert' : 'Referenz kopieren' }}
      </button>
    </div>

    <p class="booking-detail__name">{{ b.name }}</p>

    <ul class="booking-detail__positions">
      @for (position of b.positionen; track position.rowLabel + '-' + position.columnNumber) {
        <li class="booking-detail__position">
          Sitzplatz {{ position.rowLabel }}{{ position.columnNumber }} – {{ position.preiskategorie.name }} –
          {{ position.preiskategorie.preis | currency: 'EUR' }}
        </li>
      }
    </ul>

    <p class="booking-detail__total">Gesamtpreis <strong>{{ b.gesamtpreis | currency: 'EUR' }}</strong></p>
  </article>
} @else if (notAvailable()) {
  <p class="booking-detail__error" role="alert">
    Diese Buchung kann hier nicht angezeigt werden.
    <a routerLink="/buchung-abrufen">Bitte rufen Sie sie über "Buchung abrufen" erneut ab.</a>
  </p>
}

