    @if (b.status === 'aktiv') {
      <button type="button" class="booking-detail__cancel button-danger" (click)="requestCancel()">Buchung stornieren</button>
    }

    @if (b.status === 'storniert') {
      <p class="booking-detail__cancel-confirmation" aria-live="polite">Buchung storniert. Die Plätze sind wieder frei.</p>
