    @if (cancelError(); as error) {
      <p class="booking-detail__cancel-error" role="alert" aria-live="assertive">{{ error }}</p>
    }

    <dialog #cancelDialog class="booking-detail__cancel-dialog" (cancel)="dismissCancel()">
      <p>Buchung wirklich stornieren? Die Plätze werden sofort freigegeben.</p>
      <div class="booking-detail__cancel-dialog-actions">
        <button type="button" (click)="dismissCancel()" [disabled]="cancelling()">Abbrechen</button>
